KG42.register("edges-ba9a2440d702f8d7a65bafe1",{"id":"S-897085de9b68fcfe","source":"KG31-623d45f464e9bce4","type":"links","target":"KG31-c38847500f58498d","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["06-sdr_energy_sharing"],"assertions":[{"id":"06-sdr_energy_sharing::v141-c-R003::E::v141-c-R003-E001","paper":"06-sdr_energy_sharing","rule_id":"v141-c-R003","rule_ref":"06-sdr_energy_sharing::v141-c-R003","record":{"edge_id":"v141-c-R003-E001","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e28"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R003-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-623d45f464e9bce4","target":"KG31-c38847500f58498d","source_occurrence_id":"06-sdr_energy_sharing::v141-c-R003::V::coordination.local_operator","target_occurrence_id":"06-sdr_energy_sharing::v141-c-R003::V::execution.energy_trade","source_unit_id":"06-sdr_energy_sharing::v141-a-M01::coordination.local_operator","target_unit_id":"06-sdr_energy_sharing::v141-a-M01::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"ESP-mediated exchanges among PV prosumers in the energy-sharing zone. | Implementation of surplus-PV sharing through the distributed iterative process in Algorithm 1. | Organization of PV energy sharing in the proposed energy-sharing zone. | The prosumer-facing legs of ESP purchases and sales within the energy-sharing zone.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e16","v141-b-g01-e28","v141-b-g02-E-26","v141-b-g02-E-28","v141-b-g02-E-29"]},"active":true,"source_signature":"9061bce73e2e7cce63d609d74de52889375b797a793211547222c552e55ab77d","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Information, allocation, governance or payment coordination in this mechanism: ESP computes internal buying/selling prices from supply-demand ratio and grid tariffs; prosumers iteratively reschedule; preserve service-fee and balance conditions.","target_definition":"Contract performance, exchange or delivery conditions in this mechanism: ESP computes internal buying/selling prices from supply-demand ratio and grid tariffs; prosumers iteratively reschedule; preserve service-fee and balance conditions.","constraints":[{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"The ESP coordinates energy-sharing activities and executes the local trading agency role by purchasing surplus electricity from PV prosumers and selling electricity to other prosumers. Scope: ESP-mediated exchanges among PV prosumers in the energy-sharing zone.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e28"]}],"evidence":[{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-0812c00672-p03-c2r1__v141-a-M01-participation","page":3,"printed_page":"3571","section":"II. ENERGY SHARING STRUCTURE OF PV PROSUMERS / B. Energy Sharing Structure","anchor_text":"NSE FOR MICROGRIDS OF PEER-TO-PEER PROSUMERS 3571 In order to facilitate the organization of energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"In order to facilitate the organization of energy sharing, a coordinator is required. Here, we introduce a new entity named Energy Sharing Provider (ESP). Generally, the ESP may belong to the microgrid operator or an independent third party company that focuses on the business mode of energy sharing, which provides energy sharing service for all participated PV prosumers. The ESP acts as an agent for prosumers and is responsible for assuring the power balance and the payment balance in the energy sharing zone. In this regard, the ESP is in charge of purchasing electricity from the utility grid, or from the PV prosumers with extra net power export, then selling electricity to other prosumers or the utility grid."},{"evidence_id":"v141-b-g01-e28","location":{"location_id":"src-0812c00672-p02-c2r3__v141-a-M01-participation","page":2,"printed_page":"3570","section":"I. INTRODUCTION","anchor_text":"ex- with price-based DR for microgrids of P2P prosumers. The main the contributions are as follows. ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"unknown"},"source_text":"1) An energy sharing structure is proposed to integrate the autonomous PV prosumers into an energy sharing zone, and a virtual entity named energy sharing provider (ESP) is defined to coordinate the sharing activities. 2) A dynamical internal pricing model is proposed for the operation of energy sharing zone, which is defined based on the supply and demand ratio (SDR) of shared PV energy, and the feed-in tariff is considered as the price bound. 3) As the internal prices are adjusted with the change of SDR, the autonomous demand response of participants is integrated into the energy sharing, and the implementation method is also designed."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"ESP-mediated exchanges among PV prosumers in the energy-sharing zone. | Implementation of surplus-PV sharing through the distributed iterative process in Algorithm 1. | Organization of PV energy sharing in the proposed energy-sharing zone. | The prosumer-facing legs of ESP purchases and sales within the energy-sharing zone.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e16","v141-b-g01-e28","v141-b-g02-E-26","v141-b-g02-E-28","v141-b-g02-E-29"]},"source_record":{"edge_id":"v141-c-R003-E001","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e28"]},"paper_scope_note":"Retain the positive and negative net-power branches, ESP organizational responsibilities, cost valuation, and the shared service fee sub-item; the iterative price, final price, and grid trading after failure cannot be treated as identical."}}],"assertion_ids":["06-sdr_energy_sharing::v141-c-R003::E::v141-c-R003-E001"]});
